//! The bounded task-tree catalog, native since `RUSTDOC-AND-XTASK.15.h`: open trees stay on the bounded
//! landing, every real tree appears in exactly one 56-member derived part, and both are regenerated byte for byte.
//! `scripts/check_task_tree_catalog.pl` remains the argument-compatible shim.

use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

const LABEL: &str = "task-tree-catalog";
const START: &str = "<!-- task_catalog:start -->";
const END: &str = "<!-- task_catalog:end -->";
const PART_DIRECTORY: &str = "docs/task-catalog";
const PART_PREFIX: &str = "catalog-";
const TREES_PER_PART: usize = 56;
const MAX_PARTS: usize = 16;
const MAX_SECTION_BYTES: usize = 49_152;
const MAX_ROW_BYTES: usize = 512;
const VALID_STATUS: [&str; 8] = [
    "proposed",
    "active",
    "pending",
    "in_progress",
    "blocked",
    "done",
    "deferred",
    "superseded",
];

#[derive(Debug, Clone)]
struct Task {
    id: String,
    title: String,
    status: String,
    name: String,
}

#[derive(Debug)]
struct Part {
    number: usize,
    name: String,
    path: String,
    first: String,
    last: String,
    count: usize,
    content: String,
}

fn os_error(error: &std::io::Error) -> String {
    let text = error.to_string();
    text.split(" (os error").next().unwrap_or(&text).to_string()
}

fn slurp(path: &Path) -> Result<String, String> {
    fs::read_to_string(path)
        .map_err(|error| format!("cannot read '{}': {}", path.display(), os_error(&error)))
}

fn parse_task(name: &str, text: &str) -> Result<Task, String> {
    let expected_id = name.strip_suffix(".md").unwrap_or(name);
    let first = text.lines().next().unwrap_or("");
    let Some(rest) = first.strip_prefix("# ") else {
        return Err(format!("{name} lacks canonical '# TREE-ID: title' H1"));
    };
    let Some((id, title)) = rest.split_once(':') else {
        return Err(format!("{name} lacks canonical '# TREE-ID: title' H1"));
    };
    if id.is_empty()
        || !id
            .chars()
            .next()
            .is_some_and(|character| character.is_ascii_uppercase() || character.is_ascii_digit())
        || !id.chars().all(|character| {
            character.is_ascii_uppercase() || character.is_ascii_digit() || character == '-'
        })
        || title.is_empty()
    {
        return Err(format!("{name} lacks canonical '# TREE-ID: title' H1"));
    }
    let title = title.trim_start_matches([' ', '\t']);
    if title.is_empty() {
        return Err(format!("{name} lacks canonical '# TREE-ID: title' H1"));
    }
    if id != expected_id {
        return Err(format!(
            "{name} H1 id '{id}' does not match filename '{expected_id}'"
        ));
    }
    if title.len() > 240 {
        return Err(format!("{name} title exceeds 240 UTF-8 bytes"));
    }
    let status = text.lines().find_map(|line| {
        let rest = line.strip_prefix("- Status:")?;
        let rest = rest.trim_start_matches([' ', '\t']);
        let rest = rest.strip_prefix("**").unwrap_or(rest);
        let rest = rest.strip_prefix('`')?;
        let end = rest.find('`')?;
        Some(rest[..end].to_string())
    });
    let Some(status) = status else {
        return Err(format!("{name} lacks a metadata '- Status: `...`' field"));
    };
    if !VALID_STATUS.contains(&status.as_str()) {
        return Err(format!("{name} has unknown status '{status}'"));
    }
    Ok(Task {
        id: id.to_string(),
        title: title.to_string(),
        status,
        name: name.to_string(),
    })
}

fn collect_tasks(root: &Path) -> Result<Vec<Task>, String> {
    let directory = root.join("docs/tasks");
    if !directory.is_dir() {
        return Err("task directory is missing: docs/tasks".to_string());
    }
    let entries = fs::read_dir(&directory)
        .map_err(|error| format!("cannot open docs/tasks: {}", os_error(&error)))?;
    let mut names = Vec::new();
    for entry in entries {
        let entry =
            entry.map_err(|error| format!("cannot open docs/tasks: {}", os_error(&error)))?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.ends_with(".md") && name != "TEMPLATE.md" {
            names.push(name);
        }
    }
    names.sort();
    if names.is_empty() {
        return Err("catalog has no task trees".to_string());
    }
    let mut tasks = Vec::new();
    for name in names {
        if !valid_task_filename(&name) {
            return Err(format!("unsafe task filename '{name}'"));
        }
        tasks.push(parse_task(&name, &slurp(&directory.join(&name))?)?);
    }
    Ok(tasks)
}

fn valid_task_filename(name: &str) -> bool {
    let Some(stem) = name.strip_suffix(".md") else {
        return false;
    };
    !stem.is_empty()
        && stem
            .chars()
            .next()
            .is_some_and(|character| character.is_ascii_uppercase() || character.is_ascii_digit())
        && stem.chars().all(|character| {
            character.is_ascii_uppercase() || character.is_ascii_digit() || character == '-'
        })
}

fn catalog_row(task: &Task, prefix: &str) -> Result<String, String> {
    let title = task.title.replace('\\', "\\\\").replace('|', "\\|");
    let row = format!(
        "| `{}` | `{}` | {} | [open]({}{}) |",
        task.id, task.status, title, prefix, task.name
    );
    if row.len() > MAX_ROW_BYTES {
        return Err(format!(
            "{} catalog row exceeds {MAX_ROW_BYTES} UTF-8 bytes",
            task.name
        ));
    }
    Ok(row)
}

fn plan_parts(tasks: &[Task]) -> Result<Vec<Part>, String> {
    let mut parts = Vec::new();
    for (chunk_index, members) in tasks.chunks(TREES_PER_PART).enumerate() {
        let number = chunk_index + 1;
        if number > MAX_PARTS {
            return Err(format!(
                "derived catalog needs more than {MAX_PARTS} parts; raise the quantum or the part bound"
            ));
        }
        let name = format!("{PART_PREFIX}{number:04}.md");
        let path = format!("docs/task-catalog/{name}");
        let first = members.first().expect("a nonempty chunk").id.clone();
        let last = members.last().expect("a nonempty chunk").id.clone();
        let count = members.len();
        let content = render_part(number, members)?;
        parts.push(Part {
            number,
            name,
            path,
            first,
            last,
            count,
            content,
        });
    }
    Ok(parts)
}

fn render_part(number: usize, members: &[Task]) -> Result<String, String> {
    let mut lines = vec![
        format!("# Task tree catalog part {number:04}"),
        String::new(),
        "> **AUTO-GENERATED — DO NOT EDIT.** Regenerate with".to_string(),
        "> `perl scripts/check_task_tree_catalog.pl --write`.".to_string(),
        String::new(),
        "Complete membership for this range. The bounded landing is".to_string(),
        "[`docs/TASK_TREE.md`](../TASK_TREE.md); it carries the open trees and routes here for the rest.".to_string(),
        String::new(),
        "| Tree | Status | Purpose | File |".to_string(),
        "| --- | --- | --- | --- |".to_string(),
    ];
    for task in members {
        lines.push(catalog_row(task, "../tasks/")?);
    }
    lines.push(String::new());
    let content = format!("{}\n", lines.join("\n"));
    if content.len() > MAX_SECTION_BYTES {
        return Err(format!(
            "derived catalog part {number:04} exceeds {MAX_SECTION_BYTES} UTF-8 bytes"
        ));
    }
    Ok(content)
}

fn render_catalog(tasks: &[Task], parts: &[Part]) -> Result<String, String> {
    let mut lines = vec![
        START.to_string(),
        "## Task Tree Catalog".to_string(),
        String::new(),
        "This derived catalog is navigation, not execution history. Read `MEMORY.md` for the single".to_string(),
        "resume pointer, then open the owning tree for its frontier, decisions, evidence, and commits.".to_string(),
        "The author template is linked separately and is never classified as active work.".to_string(),
        String::new(),
        "### Open trees".to_string(),
        String::new(),
        "Every tree that is not `done` or `superseded` — the set a session can still act on. There is no".to_string(),
        "limit on how many task-trees exist; a finished tree stays as project history in the parts below".to_string(),
        "(ADR 0045).".to_string(),
        String::new(),
        "| Tree | Status | Purpose | File |".to_string(),
        "| --- | --- | --- | --- |".to_string(),
    ];
    for task in tasks.iter().filter(|task| !terminal(&task.status)) {
        lines.push(catalog_row(task, "tasks/")?);
    }
    lines.extend([
        String::new(),
        "### Complete catalog".to_string(),
        String::new(),
        format!(
            "All {} trees route through {} derived part(s); open a range to find an id.",
            tasks.len(),
            parts.len()
        ),
        String::new(),
        "| Part | Trees | First id | Last id |".to_string(),
        "| --- | ---: | --- | --- |".to_string(),
    ]);
    for part in parts {
        lines.push(format!(
            "| [{:04}](task-catalog/{}) | {} | `{}` | `{}` |",
            part.number, part.name, part.count, part.first, part.last
        ));
    }
    lines.extend([
        String::new(),
        "Authoring template: [`docs/tasks/TEMPLATE.md`](tasks/TEMPLATE.md).".to_string(),
        String::new(),
        END.to_string(),
    ]);
    let section = format!("{}\n", lines.join("\n"));
    if section.len() > MAX_SECTION_BYTES {
        return Err(format!(
            "catalog section exceeds {MAX_SECTION_BYTES} UTF-8 bytes"
        ));
    }
    Ok(section)
}

fn terminal(status: &str) -> bool {
    matches!(status, "done" | "superseded")
}

fn stale_parts(root: &Path, parts: &[Part]) -> Result<Vec<String>, String> {
    let directory = root.join(PART_DIRECTORY);
    if !directory.is_dir() {
        return Ok(Vec::new());
    }
    let entries = fs::read_dir(&directory)
        .map_err(|error| format!("cannot open docs/task-catalog: {}", os_error(&error)))?;
    let mut stale = Vec::new();
    for entry in entries {
        let entry = entry
            .map_err(|error| format!("cannot open docs/task-catalog: {}", os_error(&error)))?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if valid_part_filename(&name) && !parts.iter().any(|part| part.name == name) {
            stale.push(name);
        }
    }
    stale.sort();
    Ok(stale)
}

fn valid_part_filename(name: &str) -> bool {
    let Some(digits) = name
        .strip_prefix(PART_PREFIX)
        .and_then(|rest| rest.strip_suffix(".md"))
    else {
        return false;
    };
    digits.len() == 4 && digits.chars().all(|character| character.is_ascii_digit())
}

fn extract_catalog(document: &str) -> Result<String, String> {
    if document.matches(START).count() != 1 || document.matches(END).count() != 1 {
        return Err("docs/TASK_TREE.md must contain exactly one catalog marker pair".to_string());
    }
    let start = document.find(START).expect("one start marker");
    let after = &document[start..];
    let end = after.find(END).expect("one end marker") + END.len();
    if !after[end..].starts_with('\n') {
        return Err("docs/TASK_TREE.md catalog markers are malformed".to_string());
    }
    Ok(after[..=end].to_string())
}

fn replace_catalog(document: &str, expected: &str) -> Result<String, String> {
    if document.contains(START) || document.contains(END) {
        let actual = extract_catalog(document)?;
        return Ok(document.replacen(&actual, expected, 1));
    }
    let start = document.find("\n## Active Task Trees\n");
    let Some(start) = start else {
        return Err("docs/TASK_TREE.md lacks the legacy Active Task Trees section".to_string());
    };
    let end = document[start..]
        .find("\n## Directory Layout\n")
        .map(|index| start + index)
        .ok_or_else(|| {
            "docs/TASK_TREE.md lacks the legacy Active Task Trees section".to_string()
        })?;
    Ok(format!(
        "{}\n{expected}{}",
        &document[..start],
        &document[end..]
    ))
}

fn atomic_write(path: &Path, text: &str) -> Result<(), String> {
    let temporary = PathBuf::from(format!(
        "{}.task-catalog.{}",
        path.display(),
        std::process::id()
    ));
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temporary)
        .map_err(|error| {
            format!(
                "cannot create same-directory temporary '{}': {}",
                temporary.display(),
                os_error(&error)
            )
        })?;
    file.write_all(text.as_bytes()).map_err(|error| {
        format!(
            "cannot write '{}': {}",
            temporary.display(),
            os_error(&error)
        )
    })?;
    file.sync_all().map_err(|error| {
        format!(
            "cannot close '{}': {}",
            temporary.display(),
            os_error(&error)
        )
    })?;
    drop(file);
    fs::rename(&temporary, path)
        .map_err(|error| format!("cannot replace '{}': {}", path.display(), os_error(&error)))
}

fn check(root: &Path, write: bool, output: &mut dyn super::Output) -> i32 {
    match check_result(root, write, output) {
        Ok(code) => code,
        Err(error) => {
            output.err(&format!("{LABEL}: {error}\n"));
            1
        }
    }
}

fn check_result(root: &Path, write: bool, output: &mut dyn super::Output) -> Result<i32, String> {
    let tasks = collect_tasks(root)?;
    let parts = plan_parts(&tasks)?;
    let expected = render_catalog(&tasks, &parts)?;
    let index_path = root.join("docs/TASK_TREE.md");
    let current = slurp(&index_path)?;
    let open_count = tasks.iter().filter(|task| !terminal(&task.status)).count();
    if write {
        let updated = replace_catalog(&current, &expected)?;
        if updated != current {
            atomic_write(&index_path, &updated)?;
        }
        fs::create_dir_all(root.join(PART_DIRECTORY))
            .map_err(|error| format!("cannot create docs/task-catalog: {}", os_error(&error)))?;
        for part in &parts {
            let path = root.join(&part.path);
            let existing = if path.is_file() {
                slurp(&path)?
            } else {
                String::new()
            };
            if existing != part.content {
                atomic_write(&path, &part.content)?;
            }
        }
        for name in stale_parts(root, &parts)? {
            let path = root.join(PART_DIRECTORY).join(&name);
            fs::remove_file(&path).map_err(|error| {
                format!(
                    "cannot remove stale catalog part '{name}': {}",
                    os_error(&error)
                )
            })?;
        }
        output.out(&format!(
            "{LABEL}: wrote {open_count} open routes to docs/TASK_TREE.md and {} trees across {} derived catalog parts.\n",
            tasks.len(),
            parts.len()
        ));
    } else {
        let actual = extract_catalog(&current)?;
        if actual != expected {
            return Err(
                "derived landing differs; run perl scripts/check_task_tree_catalog.pl --write"
                    .to_string(),
            );
        }
        for part in &parts {
            let path = root.join(&part.path);
            if !path.is_file() {
                return Err(format!("derived catalog part is missing: {}", part.path));
            }
            if slurp(&path)? != part.content {
                return Err(format!(
                    "derived catalog part differs: {}; run --write",
                    part.path
                ));
            }
        }
        let stale = stale_parts(root, &parts)?;
        if let Some(first) = stale.first() {
            return Err(format!(
                "derived catalog part is not planned: {first}; run --write"
            ));
        }
        output.out(&format!(
            "{LABEL}: {} real task trees are linked exactly once across {} derived parts, with {open_count} open on the bounded landing.\n",
            tasks.len(),
            parts.len()
        ));
    }
    Ok(0)
}

fn self_test(output: &mut dyn super::Output) -> i32 {
    let result: Result<(), String> = (|| {
        let alpha = parse_task(
            "ALPHA.md",
            "# ALPHA: compact title\n\n## Metadata\n\n- Status: `done` (closed)\n",
        )?;
        let beta = parse_task(
            "BETA.md",
            "# BETA: title with | separator\n\n- Status: **`active`** — live\n",
        )?;
        require(alpha.status == "done", "normal parser case failed")?;
        require(beta.status == "active", "bold parser case failed")?;
        let rendered = render_catalog(&[alpha, beta], &[])?;
        require(
            rendered.contains("title with \\| separator"),
            "Markdown pipe escaping failed",
        )?;
        require(
            parse_task("GAMMA.md", "# GAMMA: title\n").is_err(),
            "missing-status case did not fail",
        )?;
        require(
            parse_task("DELTA.md", "# DELTA: title\n- Status: `finished`\n").is_err(),
            "unknown-status case did not fail",
        )?;
        require(
            parse_task("EPSILON.md", "# OTHER: title\n- Status: `done`\n").is_err(),
            "filename/H1 mismatch case did not fail",
        )?;
        let long = "x".repeat(500);
        require(
            parse_task("ZETA.md", &format!("# ZETA: {long}\n- Status: `done`\n")).is_err(),
            "oversized-title case did not fail",
        )?;

        let many: Vec<Task> = (1..=TREES_PER_PART + 3)
            .map(|index| Task {
                id: format!("T{index:03}"),
                name: format!("T{index:03}.md"),
                title: "fixture".to_string(),
                status: if index % 2 == 0 { "done" } else { "active" }.to_string(),
            })
            .collect();
        let parts = plan_parts(&many)?;
        require(parts.len() == 2, "part quantum did not bind")?;
        require(parts[0].count == TREES_PER_PART, "first part is not full")?;
        require(parts[1].count == 3, "second part has the wrong remainder")?;
        require(
            parts.iter().map(|part| part.count).sum::<usize>() == many.len(),
            "parts do not cover every tree exactly once",
        )?;
        let landing = render_catalog(&many, &parts)?;
        let open_rows = many.iter().filter(|task| task.status == "active").count();
        require(
            landing.matches("| `T").count() >= open_rows
                && many
                    .iter()
                    .filter(|task| task.status == "active")
                    .all(|task| landing.contains(&format!("| `{}` | `active`", task.id))),
            "landing must list every open tree",
        )?;
        require(
            !landing.contains("| `T002` | `done`"),
            "landing must not list a terminal tree",
        )?;
        require(
            landing.contains("task-catalog/catalog-0002.md"),
            "landing must route to its parts",
        )?;
        require(
            parts[0].content.contains("../TASK_TREE.md"),
            "part must route back to the landing",
        )?;
        require(
            parts[0].content.contains("[open](../tasks/T001.md)"),
            "part rows must resolve from the part directory",
        )?;
        let overflow: Vec<Task> = (1..=TREES_PER_PART * MAX_PARTS + 1)
            .map(|index| Task {
                id: format!("U{index}"),
                name: format!("U{index}.md"),
                title: "x".to_string(),
                status: "done".to_string(),
            })
            .collect();
        require(
            plan_parts(&overflow).is_err(),
            "part-count overflow case did not fail",
        )?;
        Ok(())
    })();
    match result {
        Ok(()) => {
            output.out("task-tree-catalog: 13/13 parser, partition, and bound tests pass.\n");
            0
        }
        Err(error) => {
            output.err(&format!("{LABEL}: {error}\n"));
            1
        }
    }
}

fn require(condition: bool, message: &str) -> Result<(), String> {
    if condition {
        Ok(())
    } else {
        Err(message.to_string())
    }
}

/// Run the catalog with the arguments its Perl shim normalized.
pub fn run(root: &Path, arguments: &[String]) -> i32 {
    run_to(root, arguments, &mut super::Terminal)
}

/// `run`, writing to `output` for the eventual native `LIVE-DOC-SIZE` orchestrator.
pub fn run_to(root: &Path, arguments: &[String], output: &mut dyn super::Output) -> i32 {
    let mut root = root.to_path_buf();
    let mut mode = "check";
    let mut arguments = arguments.iter();
    while let Some(argument) = arguments.next() {
        match argument.as_str() {
            "--check" => mode = "check",
            "--write" => mode = "write",
            "--self-test" => mode = "self-test",
            "--root" => match arguments.next() {
                Some(directory) => root = PathBuf::from(directory),
                None => {
                    output.err("task-tree-catalog: --root requires a path\n");
                    return 1;
                }
            },
            _ => {
                output.err("Usage: cargo xtask check task-tree-catalog [--check|--write|--self-test] [--root PROJECT_ROOT]\n");
                return 2;
            }
        }
    }
    if mode == "self-test" {
        self_test(output)
    } else {
        check(&root, mode == "write", output)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_real_tree_and_all_thirteen_cases_hold() {
        let root = crate::repository_root();
        let mut output = super::super::Captured::default();
        assert_eq!(
            run_to(&root, &["--self-test".to_string()], &mut output),
            0,
            "{}",
            output.text
        );
        assert_eq!(
            output.text,
            "task-tree-catalog: 13/13 parser, partition, and bound tests pass.\n"
        );
        output.text.clear();
        assert_eq!(
            run_to(&root, &["--check".to_string()], &mut output),
            0,
            "{}",
            output.text
        );
        assert!(
            output
                .text
                .contains("real task trees are linked exactly once")
        );
    }

    #[test]
    fn write_replaces_only_changed_outputs_and_removes_stale_parts() {
        let root = crate::repository_root();
        let fixture = root.join(format!(
            "generated/task-tree-catalog-write-test.{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&fixture);
        fs::create_dir_all(fixture.join("docs")).expect("fixture docs");
        copy_directory(&root.join("docs/tasks"), &fixture.join("docs/tasks"));
        copy_directory(
            &root.join("docs/task-catalog"),
            &fixture.join("docs/task-catalog"),
        );
        fs::copy(
            root.join("docs/TASK_TREE.md"),
            fixture.join("docs/TASK_TREE.md"),
        )
        .expect("landing");
        fs::write(fixture.join("docs/task-catalog/catalog-9999.md"), "stale\n")
            .expect("stale part");
        let before = fs::read_to_string(fixture.join("docs/TASK_TREE.md")).expect("landing text");
        let mut output = super::super::Captured::default();
        assert_eq!(
            run_to(&fixture, &["--write".to_string()], &mut output),
            0,
            "{}",
            output.text
        );
        assert_eq!(
            fs::read_to_string(fixture.join("docs/TASK_TREE.md")).expect("landing text"),
            before
        );
        assert!(!fixture.join("docs/task-catalog/catalog-9999.md").exists());
        let mut check_output = super::super::Captured::default();
        assert_eq!(
            run_to(&fixture, &["--check".to_string()], &mut check_output),
            0,
            "{}",
            check_output.text
        );
        let _ = fs::remove_dir_all(&fixture);
    }

    fn copy_directory(from: &Path, to: &Path) {
        fs::create_dir_all(to).expect("copy directory");
        for entry in fs::read_dir(from).expect("source directory") {
            let entry = entry.expect("source entry");
            let destination = to.join(entry.file_name());
            if entry.path().is_dir() {
                copy_directory(&entry.path(), &destination);
            } else {
                fs::copy(entry.path(), destination).expect("copy file");
            }
        }
    }
}
